n\": \"Fits a reader and persists it under prompts/ and runs/. Instrument authoring over the live workspace.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"reader-score\",\n      \"method\": \"readers\",\n      \"title\": \"Reader Score\",\n      \"engineCLI\": null,\n      \"mac\": \"Read this guide; use the named existing pane/API or engine CLI.\",\n      \"http\": \"POST /api/reader/score\",\n      \"compute\": \"existingOwner\",\n      \"outputs\": [\n        \"See the selected operation public response and immutable artifact records.\"\n      ],\n      \"restriction\": \"Workbench role; use the exact fitted reader/model identity.\",\n      \"actions\": [\n        {\n          \"id\": \"post-reader-score\",\n          \"method\": \"POST\",\n          \"path\": \"/api/reader/score\",\n          \"serviceRole\": \"workbench\",\n          \"authorityReason\": \"Exact RepE reader inference over the resident model — proxied to the interactive worker.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"finetune\",\n      \"method\": \"finetuning\",\n      \"title\": \"Finetune\",\n      \"engineCLI\": \"steerlab-server finetune --help\",\n      \"mac\": \"Read this guide; use the named existing pane/API or engine CLI.\",\n      \"http\": \"POST /api/finetune/plan; POST /api/finetune/train; POST /api/finetune/submit\",\n      \"compute\": \"existingOwner\",\n      \"outputs\": [\n        \"See the selected operation public response and immutable artifact records.\"\n      ],\n      \"restriction\": \"Plan is workbench authorship; train/submit are execution. Model recipes differ.\",\n      \"actions\": [\n        {\n          \"id\": \"post-finetune-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/finetune/plan\",\n          \"serviceRole\": \"workbench\",\n          \"authorityReason\": \"Normalizes a v2 request into the PLAN a researcher confirms in the app, reading caller-named workspace files. Nothing is scheduled and nothing is spent; it is the confirmation step, not the job.\"\n        },\n        {\n          \"id\": \"post-finetune-train\",\n          \"method\": \"POST\",\n          \"path\": \"/api/finetune/train\",\n          \"serviceRole\": \"runner\",\n          \"authorityReason\": \"Runs the LoRA training itself — GPU compute this deployment executes.\"\n        },\n        {\n          \"id\": \"post-finetune-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/finetune/submit\",\n          \"serviceRole\": \"runner\",\n          \"authorityReason\": \"The evidence-grade fine-tune path: a hash-pinned bundle submitted as a Slurm job. Submission and scheduling, in the runner's vocabulary.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"jlens\",\n      \"method\": \"jlens\",\n      \"title\": \"Jlens\",\n      \"engineCLI\": \"steerlab-server jlens --help\",\n      \"mac\": \"Read this guide; use the named existing pane/API or engine CLI. Custom artifact files: use the file-import button in the J-lens or SAE dialog; both clients expose science artifact-plan and artifact-import.\",\n      \"http\": \"GET /api/jlens/lenses; POST /api/jlens/lenses/acquire; POST /api/jlens/lenses/import; POST /api/jlens/token-options; POST /api/jlens/decode-tokens; POST /api/jlens/directions/derive; POST /api/jlens/qualify; POST /api/jlens/g0; POST /api/jlens/probe; POST /api/jlens/report; POST /api/jlens/support; POST /api/artifact-imports/plan; POST /api/artifact-imports/import\",\n      \"compute\": \"existingOwner\",\n      \"outputs\": [\n        \"See the selected operation public response and immutable artifact records.\"\n      ],\n      \"restriction\": \"Existing J-lens workbench; qualify model/lens/layer/token applicability.\",\n      \"actions\": [\n        {\n          \"id\": \"get-jlens-lenses\",\n          \"method\": \"GET\",\n          \"path\": \"/api/jlens/lenses\",\n          \"serviceRole\": \"workbench\",\n          \"authorityReason\": \"Imported-lens catalog, read-only. Catalog browsing.\"\n        },\n        {\n          \"id\": \"post-jlens-lenses-acquire\",\n          \"method\": \"POST\",\n          \"path\": \"/api/jlens/lenses/acquire\",\n          \"serviceRole\": \"workbench\",\n          \"authorityReason\": \"Fetches a lens into the HF cache. A cache fetch in shape, but the only consumer is the J-lens workbench