t.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"sae-qualification-record\",\n      \"method\": \"sae\",\n      \"title\": \"Record reviewed SAE qualification\",\n      \"engineCLI\": \"steerlab-server sae qualification record --help\",\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit\",\n      \"compute\": \"cpu\",\n      \"outputs\": [\n        \"Diagnostic path and per-layer stability summary\"\n      ],\n      \"restriction\": \"Explicit config, reviewed input hashes and a fresh engine plan are required. GPU work requires immutable model revisions. Outputs are new records; local/Slurm execution uses the existing scientific owner. Native MLX numerical equivalence is not claimed. Remote training and analysis outputs are retained; the diagnostic cleanup policy does not authorize their removal.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"sae-qualification-show\",\n      \"method\": \"sae\",\n      \"title\": \"Inspect an SAE qualification record\",\n      \"engineCLI\": \"steerlab-server sae qualification show <path> --json\",\n      \"mac\": \"Research methods: Inspect or pin SAE roster; Show qualification record. Both clients: science sae-show.\",\n      \"http\": \"POST /api/science/workspace/{action}\",\n      \"compute\": \"cpu\",\n      \"outputs\": [\n        \"See the selected operation public response and immutable artifact records.\"\n      ],\n      \"restriction\": \"Read-only inspection of existing recorded qualification. No status is inferred beyond the record.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-workspace\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/workspace/{action}\",\n          \"serviceRole\": \"workbench\",\n          \"authorityReason\": \"Author and publish local scientific requests, review and pin SAE rosters, or verify/import local custody; runner staging remains isolated execution.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    },\n    {\n      \"id\": \"jlens-fit\",\n      \"method\": \"jlens\",\n      \"title\": \"Fit a J-lens\",\n      \"engineCLI\": null,\n      \"mac\": \"Research methods: Author request, review inputs, then open execution and evidence. Both CLIs use science interview/draft/publish and the same managed engine.\",\n      \"http\": \"POST /api/science/plan; POST /api/science/submit\",\n      \"compute\": \"gpu\",\n      \"outputs\": [\n        \"Immutable fitting run, float32 Jacobians, fitting report, checkpoint, and a ready-to-import artifact description.\"\n      ],\n      \"restriction\": \"Fits with the pinned reference Jacobian estimator on a prepared, unquantized checkpoint. Start with a small timing pilot. Automatic scheduler resume is disabled; an explicit checkpoint continues in a new reviewed run. Export/fetch/import returns completed runs; artifact-plan/import then registers the lens. Partial checkpoint recovery uses permitted file transfer. Fitting is not qualification or behavioral evidence.\",\n      \"actions\": [\n        {\n          \"id\": \"post-science-plan\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/plan\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Inspect staged scientific inputs and execution resources without execution or authorship.\"\n        },\n        {\n          \"id\": \"post-science-submit\",\n          \"method\": \"POST\",\n          \"path\": \"/api/science/submit\",\n          \"serviceRole\": \"both\",\n          \"authorityReason\": \"Execute a reviewed scientific operation and retain its scientific output type.\"\n        }\n      ],\n      \"access\": {\n        \"status\": \"http\",\n        \"client\": \"runner science-call <operation> --action <action-id> --request <request.json> --runner <url> --json\",\n        \"macCLI\": \"remote science-call <operation> --action <action-id> --request <request.json> --site <id> --json\",\n        \"restriction\": \"Calls the existing route with its existing service role and scientific gates. Request path parameters, query and body remain explicit; this adapter does not change execution topology or retry mutations.\"\n      }\n    }\n  ]\n}\n",
      "extraction.md": "# Choose and extract a steering direction\n\nCompare declared activation populations before testing an intervention.\n\nChoose the contrast with the researcher. Record the construct, counter-construct or reference population, model revision, rendering, reading position and intended claim before generating data.\n\n| Method declaration | Inputs | Meaning and limitation |\n|---|---|---|\n| meanDifference | prompts/concepts/<concept>/positive.jsonl and negative.jsonl; each line has a text string | Difference of class means. Equal counts are not required by the arithmetic. Match nuisance features such as topic and register. |\n| lat | The same files, aligned row by row with equal lengths | Paired-difference PCA with normalization and alternating orientation. Order is part of this implementation's recipe. RepE-inspired, not an unchanged RepE replication. |\n| emotionGrandMean | prompts/emotions/<concept>/stories.jsonl for every named corpus member; text rows | Concept mean minus the pooled corpus mean, including the target. Corpus membership defines the comparison. |\n| designatedReference | Target and explicitly chosen reference stories.jsonl files | Difference from that reference population. Do not select a reference merely because a file exists. |\n\nA minimal stimulus row is {\"text\":\"A statement expressing the declared position.\"}. It is a schema example, not a validated stimulus set. Keep extraction stimuli, held-out probes, development tasks and final evaluation tasks separate. A neutral corpus used to denominate norm-unit alpha is another pinned input, not the negative class.\n\nUse `authoring prompt contrastive-pairs --concept <concept> --positive <definition> --negative <definition>` for paired stimuli. For story and neutral corpora, hand the coworker the text-row schema and author instructions in this guide; the prompt emitter has no dedicated kind for those corpora. Hand the resulting prompt to a coworker; independently review topic, length, register, polarity leakage, duplication and split overlap before importing. Do not treat generated data as validated evidence.\n\nDeclare with experiment attach --method and the explicit rendering/reading/reference/corpus flags shown by that client's help. Authoring is local; execution is steerlab-cli experiment extract on supported Mac cells or steerlab-server experiment extract on the Python engine. Use the client bundle workflow for supported remote stages. A template-aware reading position under raw rendering refuses; assistant-voice extraction is Python-only.\n\nInspect recipe and input pins in the vector sidecar. Then use held-out validation, a development sweep, baseline and declared controls before freezing final measurement. Cosine alignment or a stable vector alone does not establish a construct or a causal behavioral effect.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "finetuning.md": "# Prepare and compare fine-tuned adapters\n\nSeparate training-recipe choices from subsequent study claims.\n\nChoose the training objective, supervised output, dataset splits, base model/revision, target modules, scaling, seed, checkpoint-selection rule and comparison intervention with the researcher.\n\nUse the LoRA row schemas and coworker brief below, then `steerlab-server data check lora <package-manifest-or-dir> --json`. There is no LoRA kind in the generic prompt emitter. Use the workbench finetune plan operation before train or submit; the Python engine CLI also has finetune plan/train/submit. The existing Adapters pane reaches these owners. A plan is not training success, and a scheduler receipt is not a completed adapter.\n\nKeep labels, masks and split roles explicit. Compare training recipes on objective/masking, effective adapter scaling, optimization schedule, target layers, precision and checkpoint selection; shared rank or a similarly named alpha does not make two recipes matched. Preserve dataset hashes and the resolved model revision in the training artifact.\n\nInspect the produced adapter and its qualification/evaluation evidence before composing an agent. Attach the reviewed agent to an ordinary comparison study with baseline and held-out prompts. A fine-tuning improvement on its training objective is not evidence that a steering vector and adapter implement the same intervention.\n\n## Dataset rows and training declaration\n\nEvidence-grade document mode has one complete example per row:\n\n```json\n{\"id\":\"document-1\",\"text\":\"One independently sourced training document.\"}\n```\n\nInstruction-chat mode uses user/assistant text and optional system text:\n\n```json\n{\"id\":\"instruction-1\",\"system\":\"Follow the declared task.\",\"user\":\"A training input.\",\"assistant\":\"The approved target response.\"}\n```\n\nThe loader also accepts `prompt`/`completion` aliases; normalized rows use `user`/`assistant`. Unknown row keys refuse. Do not combine examples into a token stream or silently truncate them. Declare the long-document split/refuse policy. Keep training and validation files independently authored; retain a separate final evaluation corpus.\n\nThe package manifest names each arm's `adapter`, `training` and `validation` references with actual `path`/`sha256` values and the package QC report. Run the data check before authoring a training configuration. Select `document` or `instruction_chat`, base model/revision, dataset pins and evidence-grade policy explicitly in the fine-tuning plan; the workbench exposes its current request schema at `/openapi.json`. The engine CLI takes `finetune plan --config <file> --json` before `train` or `submit` with that reviewed config. An exploratory inline recipe is not interchangeable with the pinned dataset recipe.\n\nAsk the coworker to return the chosen row format, independent splits and an audit of source permissions, duplication, label correctness and systematic nuisance differences. Ask the reviewer to compare intended supervised tokens with the selected engine recipe before approving a causal comparison.\n\n## Engine config spelling\n\nThe engine CLI config is **snake_case**, unlike the workbench HTTP body's camelCase wire. Use `base_model_id`, `revision`, `training_mode`, `train_paths`, `validation_paths`, `expected_hashes` (path to actual SHA-256), `dataset_root`, `dataset_manifest_path`, `dataset_manifest_hash`, `dataset_bundle_id`, `reserved_evaluation_hashes` and `evidence_grade`. Training choices include `rank`, `alpha`, `dropout`, `learning_rate`, `target_modules`, `dtype`, `seed`, `epochs`/`max_steps`, `batch_size`, `gradient_accumulation`, `warmup_steps`, `lr_schedule`, `max_grad_norm`, `weight_decay`, `max_sequence_tokens`, `long_document_policy`, `chunk_overlap_tokens`, `eval_interval_steps`, `checkpoint_interval_steps`, `selection_metric` and `control_arm`. Unknown fields refuse. Do not paste HTTP camelCase directly into the engine config.\n\nThe plan validates this declaration and reports the dataset, schedule and evidence refusals before training. Ask about substantive unset choices; a library default is not researcher approval. Keep the complete reviewed plan beside the proposed config in the handoff.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "jlens.md": "# Acquire and qualify a J-lens\n\nInspect a lens under its model, layer and token constraints.\n\nAsk which model/revision, fitted lens, source/target layers and token-level question the researcher wants to inspect. Distinguish acquisition, arithmetic qualification, predictive readout and behavioral evidence.\n\nUse the J-lens pane or the existing jlens family and /api/jlens routes for acquisition/import, token options, direction derivation, qualification, G0, probing, report and support. Read each operation's public help or request schema. Qualification fixtures belong to the instrument; do not replace them with study-specific examples to obtain a pass.\n\nPreserve lens identity, model revision, tokenizer conventions and supported fitted layers. Imported or acquired files are not qualified solely because they load. Unknown applicability requires qualification or an explicit unsupported result.\n\nOutputs include lens metadata, qualification records and readout reports. A token ranking is a model-dependent readout; it does not by itself show that a concept caused a behavioral change. Use a separately designed steering intervention and held-out outcome measurement for that claim.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Import a custom fitted lens\n\nUse an artifact you already have. Place this description beside its tensor file;\nreplace the miniature example geometry with the actual fitted model and tensors.\nA coding agent should read the supplied source documentation and ask about missing\nmetadata, never infer a model revision or layer mapping from a filename.\n\n```json\n{\n  \"schemaVersion\": 1,\n  \"kind\": \"jlens\",\n  \"modelID\": \"example/model\",\n  \"modelRevision\": null,\n  \"hiddenSize\": 2,\n  \"layerCount\": 4,\n  \"tensorFile\": \"lens.safetensors\",\n  \"lens\": {\n    \"tier\": \"testing\",\n    \"targetLayer\": 3,\n    \"layers\": {\"0\": \"layer_0\", \"2\": \"layer_2\"},\n    \"promptsFitted\": 100,\n    \"corpus\": \"Description of the actual fitting corpus\",\n    \"maxSeqLen\": 128\n  }\n}\n```\n\nThis example declares two fitted 2×2 matrices; it does not invent the missing\nlayer 1. It supports readouts at those fitted layers; the current steering-token\nvector builder needs every source layer before the final block. Transport is\n`J_l @ h` to the final block before normalization. Optional\n`configFile` retains original source configuration bytes. Optional `source` can\nrecord a repository, its exact revision, and/or a URL; unknown values are omitted.\nKnown fit-time `modelRevision` is a 40-character commit; unknown remains null.\nSafetensors and numeric NPZ are portable; tensor-only PyTorch checkpoints and\nBF16 need the optional PyTorch reader. A saved JacobianLens `J` mapping is read as\n`layer_<number>` keys, with checkpoint geometry checked against the description.\n\nBoth clients offer `science artifact-plan <description.json> --json`, then\n`science artifact-import <description.json> --plan-sha256 <reviewed-hash> --json`.\nSelect the destination workspace with the client's usual root/workspace option.\nThe app's J-lens dialog offers **Import my own lens files** and explicitly stages\nfiles to the connected Python workbench before review. Import publishes a fresh\nlens ID, retains source copies, and does not qualify it or train anything. Use\nthat explicit lens ID when several fits exist for the same model.\n\nChoose intended use with the researcher: optional `lens.tier` is `testing`\n(the default, for rehearsal) or `evidence` (intended study use). This declaration\napplies to every custom lens, including models in the published catalog. It is\nnot a claim of validity or a passing qualification. Freezing a study with this\nreadout still needs qualification bound to the exact lens bytes, runtime, and\nlayers, plus the study's normal pins. To change intended use, update the source\ndescription, review a fresh plan, and import a new lens; keep existing artifacts\nunchanged. Published-source imports retain their existing tier policy.\n\n## Fit a new lens from your own text\n\nThe managed operation is `jlens-fit`. In the app's J-lens dialog choose\n**Fit a new lens…**, or open its interview under Research methods. Both clients\nexpose `science interview jlens-fit --json`, then the usual\n`science draft`/`publish` and execution/collection workflow. The engine uses\nthe same owner through `POST /api/science/plan` and `/api/science/submit`.\nUse an installed engine with the pinned optional `jlens` extra. Authoring is\navailable without GPU packages; fitting loads only an already-prepared model.\n\nSupply a UTF-8 JSONL corpus with exactly `id` and `text` per row:\n\n```json\n{\"id\":\"passage-1\",\"text\":\"Replace this example with a sufficiently long passage from your documented text source.\"}\n```\n\nUse text representative of the population where you will use the lens. This is\nnot paired positive/negative concept data. Preserve source and licensing details\nin the authoring notes. Keep separate text for assessing readouts; fitting\nconvergence is not held-out validity. The default considers the first four rows\nas a timing pilot. Increase the limit after inspecting cost and coverage.\nThere is no hidden shuffle or chat template. Tokenization uses the checkpoint's\nnative special-token settings; the reference position mask omits the first\n16 positions and the final token. Short rows are explicitly recorded as skipped.\n\nConfiguration fields: `modelID`, immutable 40-hex `revision`, `corpus`\n(`{path,sha256}`), optional `sourceLayers` (blank/null means every source\nlayer), `maxPrompts` (4), `maxSeqLen` (128), `skipFirst` (16),\n`dimBatch` (1), `checkpointEvery` (4), `dtype` (bfloat16),\n`device` (cuda), `tier` (testing), and optional `checkpoint`\n(`{path,sha256}` naming state.json beside sums.safetensors).\n\nThe estimator sums output cotangents over valid target positions, averages\ngradients over valid source positions, and averages the resulting matrices over\nusable prompts. The final target is the last residual block before normalization.\nSource layers are explicit; a partial lens can support readouts, while the current\ntoken-vector builder needs every source layer. Weights never change. Accumulation\nand final lens storage use float32 even when model execution uses bfloat16.\n\nCost includes one replicated forward and roughly hidden-size/dimBatch backward\npasses per usable passage. More dimensions per pass need more activation memory.\nA successful inference run does not prove that a hybrid attention implementation\nsupports this backward calculation. Measure a pilot on the actual checkpoint,\nengine, and hardware before scheduling a large fit. Runtime or numerical errors\nare reported; they are not silently counted as short corpus rows.\n\nFor a worked example (not a specification for your selected model), width 5,376\nand 61 source layers require 5,376 backward passes per usable row at dimension\nbatch 1. Each float32 matrix set occupies 6.57 GiB; sums and the current row's\nmatrices alone need 13.14 GiB of CPU memory. Each checkpoint writes about\n6.57 GiB, and model weights, activations, temporary matrices, and serialization\nneed additional space. Batch 8 processes eight dimensions together in 672\npasses, using more activation memory; it does not promise eightfold acceleration.\nEven four rows can be an expensive pilot. Measure before increasing the limit.\nThe shared request review estimates these costs from the exact model's cached\nconfiguration when available, without loading or downloading weights. Otherwise\nit reports unknown geometry and asks for review on the prepared engine. These\nare arithmetic estimates, not measured peak memory or elapsed time.\n\nCompleted fits return an immutable run with fit-report.json,\njacobians.safetensors, artifact-description.json, captured input text, and a\ncheckpoint. Use normal science export/fetch/import and verify custody to bring\nthe run home. Then review artifact-description.json with artifact-plan and use\nartifact-import to register this particular fit in the lens library. In the app,\nuse **Import my own lens files…** on that returned description. Fitting precision,\nmodel revision, corpus hash, and original report survive registration. Qualify\nthat registered lens for its intended runtime separately; fitting is not\nqualification and supplies no claim about causal behavioral meaning.\n\nPeriodic checkpoint snapshots live in the run's named\n`.steerlab/jlens-fitting-state/` scratch directory. Each snapshot is published\ncoherently before this invocation prunes its prior scratch snapshot. Completed\nruns retain an immutable final checkpoint and the source checkpoint metadata/hashes;\nprivate working copies are then removed. Cancellation retains the last completed\nscratch snapshot. Wait for the original job to stop, use the site's permitted\ntransfer tools to recover state.json and sums.safetensors together if needed,\nand select state.json in a new request. The corpus, model, numerical runtime\nsettings, dependency versions, and estimator must match under the versioned\nfitting compatibility contract. Source hashes remain recorded as provenance, so\na documentation-only change does not prevent continuation. A narrowly identified\ncheckpoint from the original fitting release is recognized under the same\ncontract; unknown older formats require review. Numerical changes require a new\ncontract or an explicitly assessed migration, not silently ignoring differences.\nThe row limit may increase; progress is never appended to the old run. Review\nand execution independently read and verify checkpoint tensors, with a status\nmessage before hashing. Multi-gigabyte files can take several minutes on slow\nstorage; do not interpret that alone as a hang.\nThe managed scheduler still reports automatic resume as unavailable: checkpoint\ncontinuation is a new, explicit reviewed job. Failed jobs are not evidence exports.\nNo general cleanup of fitting runs or recovered checkpoints is authorized.\nFailed runs accumulate intentionally. Ordinary errors after run creation,\nincluding model loading and checkpoint restoration, leave a failure record with\nthe stage, reason, and recovery references when storage permits. An abrupt kill\nor full disk can prevent that record; the run has no completion marker, and its\nlast completed scratch checkpoint remains the recovery point.\n\n### Corpus-authoring prompt to copy\n\nHelp me choose or prepare a fitting corpus for a J-lens on my selected model.\nFirst ask what text population the lens should represent and whether I want to\nuse existing files, author the text myself, or delegate data creation. Do not\ngenerate passages or launch agents without my agreement. If authoring is agreed,\nreturn UTF-8 JSONL with unique id and nonempty text fields only, with enough\ntokens after the chosen truncation and skipped-position settings. Keep source\nand licensing notes separately. Propose held-out passages separately for later\nreadout assessment. Explain that this corpus fits an averaged instrument and\ndoes not establish a behavioral concept. Do not invent model commits, execute\nfitting, or download weights.\n",
      "jspace.md": "# Inspect an intervention in J-space\n\nSeparate arithmetic fidelity, readout predictiveness and causal evidence.\n\nUse this exploratory analysis when the researcher wants to inspect the lens readout of a vector's downstream residual change. It does not train an intervention or replace a behavioral study.\n\nRun steerlab-server optvec jspace --config <file>. Required config fields are vectorArtifacts (extension-less artifact paths), lensID and probeItems:{path,sha256}. The probes are pinned choice-row JSONL. Optional observationLayers must be fitted source layers at or above the injection layer. Other supported keys include alphaMultiple, nullSeed, nullDraws, seed, topK, microbatchSize, modelID, revision, device, dtype, promptMode, systemPrompt, qwenThinkingEnabled and name. Unknown keys refuse.\n\nAsk the researcher to choose the vector, lens, probes, observation layers and dose. Obtain hashes from inspected bytes, never fabricate them. alphaMultiple scales the artifact's own norm; it is not the ordinary residual-norm alpha. The seed field is inert here because no generation sampling occurs; nullSeed governs matched-norm random draws.\n\nReport arithmetic fidelity and precision-floor flags separately from predictive readout. Null draws are comparators, not a calibrated test. Behavioral/causal evidence is absent from this operation; collect it through a separate controlled run. The engine CLI is the supported execution path; the app guide exposes that restriction explicitly.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n\nJ-space is an analysis method, not an OptVec training procedure. Its public managed operation is `jspace`. The historical engine command `optvec jspace` currently accepts OptVec artifacts because it reads their stored layer and absolute dose; that implementation restriction is not a claim that J-space depends scientifically on optimization. Other intervention artifact types require a separate admission change.\n",
      "judging.md": "# Complete deferred judgments\n\nMaintain blinding, packet identity and the declared judge panel.\n\nDecide the rubric, judge panel, evaluation sample and intended reliability claim before scoring. Use independent judgments rather than asking a coding agent to invent favorable labels.\n\nInspect experiment sweep/evaluate awaiting through the existing workbench/runner endpoints. Hand each coworker the pinned blinded packets and their instructions, not an unblinded arm map. Require the operation's exact judgment row schema, packet IDs, judge identities and instruction pins; never fabricate missing judgments or edit packet files to make coverage pass.\n\nComplete through the existing sweep/evaluate complete-judgment routes or `steerlab-server experiment complete-sweep-judgment` (sweep) and `steerlab-server experiment complete-judgment` (evaluate). Both take `<study> --awaiting-run <run> --judgments <file> --json`. These owners verify coverage, packet hashes and epoch. A sweep completion can append the selected recommendation to a draft; evaluate completion aggregates judgment evidence. Preserve that distinction and the owners' lifecycle gates.\n\nOutputs are judgment records, agreement/report data and, where applicable, the recommendation. Judge agreement alone does not establish validity. Missing/partial coverage, stale packets or a changed study must produce the owner's repair, not an automatic retry with new pins.\n\n## Intake shape and blinding\n\nFetch `GET /api/experiment/{name}/sweep/awaiting` or `GET /api/experiment/{name}/evaluate/awaiting` on the selected engine. An example row shape is:\n\n```json\n{\"packetID\":\"issued-packet-id\",\"judge\":\"declared-judge-id\",\"winner\":\"A\",\"model\":\"declared-judge-model\"}\n```\n\nIDs/model strings above are placeholders for the issued packet and pinned judge, never new identities. Winner is `A`, `B` or `tie`. CLI input accepts a JSON list, a `{\"judgments\":[...]}` object, or JSONL. HTTP bodies name `sweepRun` or `evaluateRun` plus `judgments`. Evaluation accepts the optional `instructionsSha256` claim; its owner records mismatches as warnings, not a hard gate. Sweep has no such claim field; its CLI refuses one rather than dropping it.\n\nSupply the full packet × judge coverage required by the issued manifest, including the actual model/annotator declarations it requests. A coder should prepare delivery and check completeness without seeing the unblinding map; independent judging coworkers see only the assigned blinded packets and pinned instructions. Completion is idempotent: an existing result can be returned, and a sweep may heal a missing draft recommendation projection. It does not rewrite its source evidence.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "multi-agent.md": "# Design a multi-agent study\n\nDeclare interaction structure and controls before casting agents.\n\nAsk about roles, shared materials, private information, turn order, visibility/routing, stopping rules and measured outcomes. Specify baseline, each-solo and combined-treatment comparisons where they answer the question; do not assume a composition sweep is the research design.\n\nUse authoring study multiAgent for the shared interview and study-pack skeleton. Semantic panel JSON describes roles, materials, turns, routing, contracts and outcomes. Model settings and agent artifacts belong in the study's casting. Task prompts do not substitute for a panel transcript.\n\nPublish with panel import after checking source bytes. Inspect the panel and agents, then panel compile with the reviewed study and input digests and every seat explicit (null for baseline). Compilation changes studyKind and studyType to multi-agent, including when the source draft was a concept study. Review that intent before applying it; duplicate a draft if the original design must remain available.\n\nUse design expand to preview distinct permutations or baseline/each-solo/all-treated batch rows. Review the rows before design batch, then preserve successful publications if a later row fails. The study authorship interfaces share these owners; Python executes panel turns on its supported runner.\n\nOutputs are compiled pinned scenarios and transcripts with declared outcome measurements. More agents do not imply independent observations. State the unit of analysis, interference assumptions, visibility policy and transcript-judging plan.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "optimization.md": "# Optimize a steering vector\n\nTrain an intervention against a declared objective and evaluate it on separate data.\n\nAsk the researcher to specify the objective, construct, counterfactual/control, model/revision, injection sites, dose convention and train/dev/test split. Optimization data and final evaluation data have different roles.\n\nAuthor the choice-row bundle below, then run `steerlab-server data check optvec --dir <directory> --json`. The prompt emitter has no OptVec-specific kind; use the coworker brief in this guide. Preserve item IDs, option order, declared target labels and pinned split files. Do not infer target labels from option length, topic or a conveniently available answer column.\n\nThe engine's optvec family exposes train, eval, geometry, interpret, family, fracture, gradient, jspace and campaign. Use the exact operation references below and each verb's public help; their closed config validators are the authority. In the app, Data → OptVec starts with Train a vector, Evaluate a vector, and Plan a campaign. Data → Concepts & Vectors also opens the training form. These use the same managed operation owners as the agent client. OptVec learns a vector by optimizing an objective; a steering-strength sweep tests already chosen directions at different strengths. J-space analysis is a separate coordinate analysis, not another name for OptVec training.\n\nTraining produces a vector artifact and optimization record. Evaluate held-out behavior and capability costs; geometric similarity, a training objective improvement and a family plot answer different questions. Report checkpoint selection and the dose actually tested. Never tune a final test split or describe a null-direction comparison as a calibrated statistical test without a declared test design.\n\n## Dataset bundle and author brief\n\nA choice row declares the target explicitly, even though the loader has a default:\n\n```json\n{\"id\":\"target-train-1\",\"prompt\":\"A described situation. Choose A or B.\",\"options\":[\"A\",\"B\"],\"target\":\"B\"}\n```\n\nAuthor `target-train.jsonl`, `target-val.jsonl`, `target-test.jsonl`, `anchor-train.jsonl`, `anchor-val.jsonl`, `anchor-test.jsonl`, `capability-train.jsonl`, `capability-eval.jsonl` and `neutral-fluency.jsonl` (text rows). Keep IDs unique across all files, target A/B balance within 45–55% per choice file, and content/fact patterns disjoint across splits. Tokenizer checks still have to establish single-token options on the pinned model; a single character does not prove that.\n\nPublish `bundle.json` with nonempty `targetIssue`, `shiftDirection`, `caseFamilies` and `anchorIssues`, and a `files` object whose entries each contain `path` and the actual file `sha256`. Include `REPORT.md` with leakage/nuisance checks and unresolved scientific questions. These are dataset records, not changes to an existing study manifest. Use the readiness result's hashes and the selected operation's closed config; never copy placeholder hashes into a training declaration.\n\nGive the coworker the approved target direction, families of situations, invariant anchor judgments and capability domains. Ask for the complete bundle and separate QC report; give another reviewer the inputs and rationale before any training. A predeclared fixed-steps training configuration can omit target validation; report that choice and do not silently reuse the test set for checkpoint selection.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n",
      "readers.md": "# Train and use an activation reader\n\nMeasure an activation-based instrument separately from an intervention.\n\nDecide the construct, template, label interpretation, training split, held-out evaluation split and scoring position with the researcher. A reader's score is not automatically an intervention or a behavioral outcome.\n\nUse the existing reader template registry and reader fit/score interfaces. Request the schema and authoring prompt for the selected template; do not substitute ordinary contrastive-pair files for template-mediated reader inputs. Preserve label alignment, model revision, tokenizer/rendering settings and the exact fitted artifact.\n\nInspect the Readers pane or POST /api/reader/fit and /api/reader/score on a workbench engine. The registry below names supported public paths; these workbench routes are not advertised as batch-runner submissions. Treat training accuracy separately from held-out instrument performance. If importing a reader-derived steering vector, use experiment inspect-artifact and attach-artifact with exact artifact/sidecar/manifest reviews and retain its reader provenance.\n\nOutputs are the fitted reader artifact and scored records. Report the training/evaluation split and applicability to this model and rendering. A successful fit does not establish causal control of the named construct.\n\n## Dataset and handoff\n\nChoose exactly one row shape. `contentPair` compares content under one template:\n\n```json\n{\"id\":\"pair-1\",\"concept\":\"construct\",\"positiveStimulus\":\"First matched text.\",\"negativeStimulus\":\"Second matched text.\",\"topic\":\"shared topic\",\"split\":\"train\",\"templateID\":\"chosen-template\"}\n```\n\n`singleStimulus` compares two template instructions on the same content:\n\n```json\n{\"id\":\"row-1\",\"concept\":\"construct\",\"stimulus\":\"An ambiguous situation.\",\"topic\":\"shared topic\",\"split\":\"train\",\"templateID\":\"chosen-template-pair\"}\n```\n\nEmit `authoring prompt reader-pairs --concept <concept> --positive <definition> --negative <definition> --template-id <template> --shape <contentPair|singleStimulus> --json`. Trailing `split:\"test\"` rows orient the fitted sign in this implementation; reserve an additional independent evaluation set before making a generalization claim. Do not relabel sign-selection data as untouched final evaluation. Templates are real registered inputs, not arbitrary IDs to invent. The fit/score request schema is available in the workbench's `/openapi.json`.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n",
      "sae.md": "# Analyze and import SAE features\n\nPreserve feature identity and the import/normalization convention.\n\nChoose the model, release, layer, width, feature IDs and intended use before searching for persuasive examples. In the app, Data → Concepts & Vectors → Import an SAE feature accepts explicit identifiers or a Neuronpedia feature link. Link lookup uses the installed SAELens directory; it never guesses an unknown mapping or downloads weights. The researcher reviews the selected feature and calibration before import can download weights. Analysis → Compare with Gemma Scope features compares existing vectors with features. Agents use `steerlab-server gemmascope resolve-feature --url <link>`, then `gemmascope import-id`, or the corresponding `/api/gemmascope` operations. The sae family exposes check, pin, family-report and qualification operations.\n\nInputs are release/model metadata, feature identity and any declared analysis corpus. A feature selected from a report and a feature imported directly by ID have different normalization conventions. Preserve the sidecar's gemmascopeConvention: analyzed-vector-norm-match for report-ranked imports, residual-norm-match for direct feature-ID imports. An unstamped legacy artifact requires the documented re-import/qualification repair before evidence use.\n\nUse experiment inspect-artifact and attach-artifact to attach the actual tensor and sidecar with their reviewed hashes. Never relabel a decoder row as an ordinary contrastive extraction or rewrite an old artifact stamp by hand.\n\nOutputs are analysis/qualification records and immutable vector artifacts with feature provenance. Reconstruction, activation examples and steering effects are separate measurements. Report selection criteria, held-out behavior and capability costs; an interpretable feature name is not independent construct validation.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n\nThe offline roster paths are `science sae-check <roster>`, `science sae-show <qualification>`, and `science sae-pin-plan <roster> --experiment <draft>`. Pin with `science sae-pin <roster> --experiment <draft> --plan-sha256 <reviewed-hash>`. Paths are workspace-relative. Both CLIs and the app call the same portable owner. The workbench endpoint uses actions `sae-check`/`sae-show` with `workspaceRoot` and `path`, and `sae-pin-plan`/`sae-pin` also take `experiment`; pin adds `planSHA256`. These are workbench operations, never runner authorship.\n\n## Import a custom decoder or an exported feature\n\nSupply a fitted decoder you already have, or one already-exported feature.\nA coding agent should consult the artifact's documentation for the model, feature\naxis, and hook site, and ask you about missing metadata. The miniature example\nbelow uses a two-dimensional residual space only to illustrate the file format.\n\n```json\n{\n  \"schemaVersion\": 1,\n  \"kind\": \"sae-decoder\",\n  \"modelID\": \"example/model\",\n  \"modelRevision\": null,\n  \"hiddenSize\": 2,\n  \"layerCount\": 4,\n  \"tensorFile\": \"decoder.safetensors\",\n  \"calibrationArtifact\": \"runs/calibration/donor\",\n  \"sae\": {\n    \"layer\": 1,\n    \"feature\": 7,\n    \"decoderKey\": \"W_dec\",\n    \"featureAxis\": \"rows\",\n    \"site\": \"resid_post\",\n    \"label\": \"Candidate behavior\"\n  }\n}\n```\n\nUse actual dimensions and a calibration artifact measured on the same Python\nmodel. `featureAxis` is `rows` or `columns` for a decoder matrix, or `vector` for\none already-exported one-dimensional feature. With `vector`, `feature` records\nits original feature number. The vector is scaled to the measured residual norm;\nthe donor supplies geometry and scale, not a semantic label. Known fit revisions\nmust match; null stays unknown. Source tensors must be finite and nonzero at the\nselected feature. This path applies a residual-post direction; other hook sites\nneed a matching intervention, and full latent SAE manipulation needs more than\none decoder vector.\n\nSafetensors and numeric NPZ work with the lightweight client. Tensor-only PyTorch\ncheckpoints and BF16 require the optional PyTorch reader. Optional `configFile`\nretains original configuration bytes; optional `source` records a repository,\nits exact revision, and/or a discovery URL without claiming a network fetch.\n\nUse `science artifact-plan <description.json> --json`, then\n`science artifact-import <description.json> --plan-sha256 <reviewed-hash> --json`\nthrough either client, with its usual destination workspace option. In the app,\nchoose **Import my own SAE decoder files** in the SAE dialog. The destination\nworkbench must already have the calibration artifact named in the description.\nStage and review copies files, and Import publishes a new vector with retained\nsource bytes. It never trains an SAE, invents data, or proves the feature label.\n",
      "stability.md": "# Diagnose extraction stability\n\nCheck sensitivity to resampling without mistaking it for behavioral validation.\n\nSelect a concept already declared in a study, its supported meanDifference or lat recipe, model/revision, resample count, fraction and seed. LAT additionally has order-shuffle sensitivity because row order enters its arithmetic.\n\nThe stability operation captures the same extraction rows as the engine, then resamples them. It writes a diagnostic outside immutable runs and does not replace the pinned vector. Read stimulusDrift: the diagnostic can report live stimulus bytes that differ from the study's pins. Restore/review those inputs rather than interpreting the result as a reading of the old artifact.\n\nUse `steerlab-server experiment extract-stability <study> <concept> --resamples 32 --fraction 0.8 --seed 1 --json` on the compute host. For a managed remote job, use `runner science-plan` / `runner science-submit` (Python client), `remote science-plan` / `remote science-submit` (Mac), or `POST /api/science/plan` and `/api/science/submit`. Supply operation `stability` with parameters `experiment`, `concept` and optional `resamples`, `fraction`, `seed`, `orderShuffles`, `dtype`, `device`. Submit the exact returned `planSHA256`. Use `science input-plan` and `science package` to review and capture local inputs. Transfer the archive under the declared policy, then `runner science-stage` (Mac `remote science-stage`) returns the isolated execution request. Plan and submit in the same controller session; restart requires a new plan. The child rechecks inputs after queueing, and the job retains the diagnostic path. It does not resume from a checkpoint. CPU resampling still requires a model activation capture first. Mac numerical parity is not claimed; a Mac user can run the Python engine through its captured endpoint.\n\nReport per-layer cosine movement, sign flips and the resampling settings. Stability does not show behavioral efficacy, construct specificity or a safe dose. Follow with held-out validation and a controlled behavioral study; do not invent a universal acceptance threshold.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\nRemote requests accept the seed as an unsigned integer or decimal string; plans return decimal text to preserve all UInt64 digits across clients.\n\nCompleted diagnostics can travel home through `runner science-fetch` (Mac `remote science-fetch`) or permitted external transfer followed by `science import`. `science custody` and `science verify-custody` re-read retained archives and expanded files offline. A verified receipt proves byte custody, not scientific qualification. Managed removal requires a declared server retention policy, reviewed `cleanup-plan`, fresh local verification and explicit `cleanup-apply --confirm-removal`; only isolated successful diagnostic output copies are eligible. Inputs, export archives, job records and local evidence are retained.\n",
      "style.md": "# Rescore recorded generations\n\nCompute declared style features without rerunning generation.\n\nChoose the taxonomy, source run and interpretation with the researcher. The study must pin the intended taxonomy; the source must satisfy the owner's epoch checks.\n\nUse experiment rescore-style on the Mac or Python engine. There is no dedicated HTTP rescoring route. This is CPU-only post-hoc computation over recorded sampled generations. The source run is immutable: outputs go to a fresh rescore run with reasoning-style.csv and reasoning-style.json.\n\nKeep this explicitly post-hoc when the features were chosen after seeing outputs. A style score is not a new generation, an extraction, a judge verdict or proof of a psychological state. Report taxonomy/source pins, missing outputs and whether the feature definitions were preregistered. Do not bypass an epoch refusal by rewriting the manifest or source metadata.\n\n## Explicit source\n\nOn the Mac: `steerlab-cli experiment rescore-style <study> --run <run> --json`.\nOn the Python engine: `steerlab-server experiment rescore-style <study> --source <run> --json`.\nThese source flags deliberately retain their existing spellings. Read `result.runDirectory` from the Python response; the output contains the new reasoning-style CSV/JSON. Choose and pin the taxonomy before rescoring. Do not describe a post hoc taxonomy choice as preregistered, or use a legacy-epoch override without the researcher's explicit acceptance of that limitation.\n\n## Coworker author prompt\n\nHelp author the inputs for this method. First restate the researcher-approved construct, comparison, model/revision, input roles and proposed claim. List unresolved scientific choices as questions; do not choose them silently. Use the schema and public operations above and the selected authoring prompt. Return proposed files separately from an audit describing split independence, labels, nuisance balance, applicability and missing facts. Do not execute, invent pins, or overwrite evidence.\n\n## Independent review prompt\n\nReview the proposed inputs without assuming the author is correct. Check the declared method, schema, labels, split overlap, source/identity pins, baseline and controls, rendering/sampling settings and whether the requested claim follows from the planned measurements. Separate mechanical checks from scientific judgment. Name each blocker and its repair; passing a parser is not scientific validation.\n\n## Shared method authoring and managed execution\n\nUse `science interview <operation> --json` to read the exact form fields used by the app. Answer the purpose, proposed claim, controls and selection questions; supply field values as strings (including integer seeds) and put reviewed extra engine settings in `advanced`. `science draft <operation> --answers <answers.json> --json` resolves file hashes and reports all captured inputs without execution. `science publish <operation> --answers <answers.json> --destination requests/<new-name> --plan-sha256 <reviewed-hash> --json` publishes the machine request and rationale together, refusing changed inputs or an existing destination. Both commands are available under each client executable.\n\nUse the resulting request file with `science input-plan` and `science package`, transfer and stage through the declared site policy, then review and submit the engine plan. The shared form is an authoring aid; the engine still checks its complete scientific config before execution. A successful parser or custody check is not scientific qualification. The workbench API exposes the same local owner at `POST /api/science/workspace/{action}`; it takes `workspaceRoot`, `operation`, and for draft/publish `answersText` (the exact JSON text). Publish also requires `destination` and `planSHA256`. Runner services cannot author the local workspace.\n",
      "workflows.json": "{\n  \"schemaVersion\": 1,\n  \"answerSchema\": {\n    \"purpose\": \"Research question in plain language\",\n    \"claim\": \"Proposed claim and its limits\",\n    \"controls\": \"Comparisons and controls\",\n    \"selection\": \"Training/selection/test separation or explanation of why it does not apply\",\n    \"fields\": \"Map of field IDs to text values. Omitted or blank optional fields use the interview default when present; required fields cannot be blank. Integers preserve their values without floating-point conversion.\",\n    \"advanced\": \"Optional original config fields; cannot overwrite form fields\"\n  },\n  \"operations\": [\n    {\n      \"id\": \"optvec-train\",\n      \"title\": \"Train a steering vector\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Teach a vector to favor a chosen answer over an alternative, while preserving other judgments and abilities. Start with your own choice prompts or prompts prepared from study outputs.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Injection layer\",\n          \"kind\": \"integer\",\n          \"required\": true,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"alphaNormFactor\",\n          \"label\": \"Dose in residual-norm units\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"Steering strength relative to the model’s typical activation size. For example, 0.1 means one tenth of the measured residual norm. This is not a J-space artifact-norm multiple.\",\n          \"default\": \"0.1\"\n        },\n        {\n          \"id\": \"residualNormArtifact\",\n          \"label\": \"Artifact supplying the residual norm\",\n          \"kind\": \"artifact\",\n          \"required\": false,\n          \"help\": \"Choose an inspected artifact with a residual norm table, or explicitly provide alphaAbsolute under advanced settings.\"\n        },\n        {\n          \"id\": \"datasets.targetTrain\",\n          \"label\": \"Target training items\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Examples of the behavior to change. For each prompt, state two answer choices and the answer to encourage. Training increases its log-probability relative to the other choice. Study outputs must first be authored into this choice-row format; they are not consumed directly. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.targetVal\",\n          \"label\": \"Selection / validation items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Separate examples of the same behavior, used for checkpoint selection or monitoring. Do not reuse training or final-test rows. A declared fixed-step run can omit this file. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.anchorTrain\",\n          \"label\": \"Behaviors to preserve\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Judgments you want to leave unchanged. The optimizer penalizes changes to the unsteered model’s answer probabilities on these prompts, rather than teaching the target label as a new answer. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.anchorVal\",\n          \"label\": \"Anchor validation items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Separate preservation examples for checking whether the trained vector changes judgments you meant to preserve. Keep them distinct from the preservation training rows. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.capabilityTrain\",\n          \"label\": \"Capability training controls\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Questions with objectively correct answers, such as basic reasoning or factual tasks. Here target is the correct answer; the optimizer penalizes losing it. Use examples relevant to the abilities your study needs. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"stepsMax\",\n          \"label\": \"Maximum optimization steps\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Upper limit on optimizer updates, not the number of examples. The existing default is a starting setting to review, not a recommended value for every study.\",\n          \"default\": \"500\"\n        },\n        {\n          \"id\": \"seed\",\n          \"label\": \"Random seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Record the seed before execution.\",\n          \"default\": \"0\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Training objective improvement is not held-out behavioral validation.\",\n      \"questions\": [\n        \"What behavior should change, and in which direction?\",\n        \"Which judgments and capabilities must remain stable?\",\n        \"Is checkpoint selection based on validation, or are fixed steps predeclared? Keep final test data separate.\"\n      ]\n    },\n    {\n      \"id\": \"optvec-eval\",\n      \"title\": \"Evaluate an optimized intervention\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Measure held-out behavior, capability costs and dose dependence.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"vectorArtifact\",\n          \"label\": \"Intervention to test\",\n          \"kind\": \"artifact\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"datasets.targetTest\",\n          \"label\": \"Held-out target test items\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Unseen examples for measuring the desired behavior after training and selection. Keep these out of training and checkpoint selection. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.anchorTest\",\n          \"label\": \"Held-out anchor items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Unseen preservation examples for measuring changes to other judgments after training. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"datasets.capabilityEval\",\n          \"label\": \"Held-out capability items\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Unseen questions with correct target answers for checking retained abilities. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"neutralTexts\",\n          \"label\": \"Neutral fluency texts\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Independent passages for checking whether steering harms ordinary language fluency. Use one passage per line, either plain text or a JSON object with a text field. These are not multiple-choice training rows. The example illustrates syntax only; choose passages suitable for your study.\",\n          \"example\": \"{\\\"text\\\": \\\"Describe how to organize a bookshelf.\\\"}\"\n        },\n        {\n          \"id\": \"alphaMultiples\",\n          \"label\": \"Multiples of the trained dose\",\n          \"kind\": \"numbers\",\n          \"required\": true,\n          \"help\": \"\",\n          \"default\": \"0.5, 1, 2\"\n        },\n        {\n          \"id\": \"seed\",\n          \"label\": \"Random seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Record the seed before execution.\",\n          \"default\": \"0\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Test results cannot be reused to select the training checkpoint without declaring that selection.\",\n      \"questions\": [\n        \"Which files were kept out of training and checkpoint selection?\",\n        \"Which dose grid and controls were fixed before seeing these results?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-geometry\",\n      \"title\": \"Compare vector geometry\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Describe similarity and multiplicity among declared intervention artifacts.\",\n      \"fields\": [\n        {\n          \"id\": \"artifacts\",\n          \"label\": \"Vector artifacts, one per line\",\n          \"kind\": \"artifacts\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Layer (optional consistency check)\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Geometric similarity or clustering is not behavioral equivalence or a calibrated statistical test.\",\n      \"questions\": [\n        \"Which independent solutions are being compared?\",\n        \"What would similarity or separation mean for the research question?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-fracture\",\n      \"title\": \"Describe solution basins\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Describe similarity and multiplicity among declared intervention artifacts.\",\n      \"fields\": [\n        {\n          \"id\": \"artifacts\",\n          \"label\": \"Vector artifacts, one per line\",\n          \"kind\": \"artifacts\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Layer (optional consistency check)\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"items\",\n          \"label\": \"Artifact-to-item grouping\",\n          \"kind\": \"documentFile\",\n          \"required\": false,\n          \"help\": \"Choose a JSON map prepared from declared item identities; never infer grouping from filenames.\"\n        },\n        {\n          \"id\": \"gradients\",\n          \"label\": \"Optional gradient tensor file\",\n          \"kind\": \"file\",\n          \"required\": false,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"threshold\",\n          \"label\": \"Clustering cosine threshold\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"0.8\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Geometric similarity or clustering is not behavioral equivalence or a calibrated statistical test.\",\n      \"questions\": [\n        \"Which independent solutions are being compared?\",\n        \"What would similarity or separation mean for the research question?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-interpret\",\n      \"title\": \"Interpret an optimized intervention\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Read logit-lens, probe, optional SAE/J-lens and library measurements.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"vectorArtifact\",\n          \"label\": \"Intervention to inspect\",\n          \"kind\": \"artifact\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"probePrompts\",\n          \"label\": \"Held-out probe prompts\",\n          \"kind\": \"fileRef\",\n          \"required\": false,\n          \"help\": \"Held-out prompts for inspecting the trained vector’s behavior. Use one prompt per line, either plain text or a JSON object with a text field. These are not multiple-choice training rows. The example illustrates syntax only; choose prompts suitable for your study.\",\n          \"example\": \"{\\\"text\\\": \\\"Describe how to organize a bookshelf.\\\"}\"\n        },\n        {\n          \"id\": \"alphaMultiples\",\n          \"label\": \"Artifact dose multiples\",\n          \"kind\": \"numbers\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"1\"\n        },\n        {\n          \"id\": \"jlensLensID\",\n          \"label\": \"Optional imported J-lens ID\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"seed\",\n          \"label\": \"Random seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"Record the seed before execution.\",\n          \"default\": \"0\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Self-explanations and readouts are suggestive measurements, not independent causal evidence. Optional failed stages remain visible.\",\n      \"questions\": [\n        \"Which readouts are relevant to the proposed claim?\",\n        \"Which optional stages and comparison libraries are predeclared?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-family\",\n      \"title\": \"Summarize interpretation readings\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Compare multiple completed interpretation reports.\",\n      \"fields\": [\n        {\n          \"id\": \"interpretRuns\",\n          \"label\": \"Interpretation runs, one per line\",\n          \"kind\": \"files\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"matchNullPercentile\",\n          \"label\": \"Descriptive match percentile\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"95\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"A family summary reports descriptive matches; it does not establish a causal taxonomy.\",\n      \"questions\": [\n        \"Which completed interpretation readings belong in this family?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-gradient\",\n      \"title\": \"Survey per-item gradient directions\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Measure local derivatives and their finite-dose behavior.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"The exact version of the model. Inspect the selected model to fill its commit automatically; an agent can also supply a verified commit. This prevents silently switching model versions.\"\n        },\n        {\n          \"id\": \"layer\",\n          \"label\": \"Injection layer\",\n          \"kind\": \"integer\",\n          \"required\": true,\n          \"help\": \"The transformer layer where the learned vector is added (zero-based). Choose a layer supported by your model and study design; no universal best layer is assumed.\"\n        },\n        {\n          \"id\": \"datasets.targetTrain\",\n          \"label\": \"Survey items\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Examples of the behavior to change. For each prompt, state two answer choices and the answer to encourage. Training increases its log-probability relative to the other choice. Study outputs must first be authored into this choice-row format; they are not consumed directly. Use one JSON object per line (.jsonl), with distinct item IDs across splits. The example below illustrates syntax only; it is not a ready-made research dataset.\",\n          \"example\": \"{\\\"id\\\": \\\"example-1\\\", \\\"prompt\\\": \\\"A box contains two red balls and one blue ball. Which color is more common? A: red. B: blue. Answer A or B.\\\", \\\"options\\\": [\\\"A\\\", \\\"B\\\"], \\\"target\\\": \\\"A\\\"}\"\n        },\n        {\n          \"id\": \"alphaNormFactor\",\n          \"label\": \"Dose in residual-norm units\",\n          \"kind\": \"number\",\n          \"required\": false,\n          \"help\": \"Steering strength relative to the model’s typical activation size. For example, 0.1 means one tenth of the measured residual norm. This is not a J-space artifact-norm multiple.\",\n          \"default\": \"0.1\"\n        },\n        {\n          \"id\": \"residualNormArtifact\",\n          \"label\": \"Artifact supplying the residual norm\",\n          \"kind\": \"artifact\",\n          \"required\": false,\n          \"help\": \"Choose an inspected artifact with a residual norm table, or explicitly provide alphaAbsolute under advanced settings.\"\n        },\n        {\n          \"id\": \"doseLadder\",\n          \"label\": \"Positive dose fractions\",\n          \"kind\": \"numbers\",\n          \"required\": true,\n          \"help\": \"\",\n          \"default\": \"0.25, 0.5, 1\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"An alpha-to-zero derivative need not describe effects at a usable finite dose.\",\n      \"questions\": [\n        \"Which item population is being surveyed?\",\n        \"What dose ladder tests the local approximation?\"\n      ]\n    },\n    {\n      \"id\": \"optvec-gradient-mint\",\n      \"title\": \"Publish one surveyed direction\",\n      \"method\": \"optimization\",\n      \"purpose\": \"Create a new vector artifact from an explicitly selected survey item.\",\n      \"fields\": [\n        {\n          \"id\": \"surveyRun\",\n          \"label\": \"Completed gradient survey run\",\n          \"kind\": \"file\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"itemID\",\n          \"label\": \"Explicit item ID\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Selecting an item after inspection is a selection decision; record the rationale before downstream testing.\",\n      \"questions\": [\n        \"Why was this item selected, and where will its direction be tested independently?\"\n      ]\n    },\n    {\n      \"id\": \"jspace\",\n      \"title\": \"Analyze an intervention in J-space\",\n      \"method\": \"jspace\",\n      \"purpose\": \"Inspect downstream residual changes through an imported J-lens. This does not optimize or train a vector.\",\n      \"fields\": [\n        {\n          \"id\": \"modelID\",\n          \"label\": \"Model to execute\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Choose the prepared model; this does not acquire weights.\"\n        },\n        {\n          \"id\": \"revision\",\n          \"label\": \"Model commit\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"Inspect the immutable 40-character model commit. Never type a guessed pin.\"\n        },\n        {\n          \"id\": \"vectorArtifacts\",\n          \"label\": \"Intervention artifacts, one per line\",\n          \"kind\": \"artifacts\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"lensID\",\n          \"label\": \"Imported J-lens ID\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"probeItems\",\n          \"label\": \"Pinned choice-row probes\",\n          \"kind\": \"fileRef\",\n          \"required\": true,\n          \"help\": \"Choose a workspace-relative file. Its actual SHA-256 is read during review.\"\n        },\n        {\n          \"id\": \"observationLayers\",\n          \"label\": \"Observation layers (comma-separated)\",\n          \"kind\": \"integers\",\n          \"required\": false,\n          \"help\": \"Only fitted source layers at or above injection; leave blank for the engine’s eligible ladder.\"\n        },\n        {\n          \"id\": \"alphaMultiple\",\n          \"label\": \"Multiple of the artifact’s own norm\",\n          \"kind\": \"number\",\n          \"required\": true,\n          \"help\": \"This is not ordinary residual-norm alpha.\",\n          \"default\": \"1\"\n        },\n        {\n          \"id\": \"nullSeed\",\n          \"label\": \"Matched-direction null seed\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"20260810\"\n        },\n        {\n          \"id\": \"nullDraws\",\n          \"label\": \"Matched-direction comparisons\",\n          \"kind\": \"integer\",\n          \"required\": false,\n          \"help\": \"\",\n          \"default\": \"1\"\n        },\n        {\n          \"id\": \"name\",\n          \"label\": \"Name for this reading\",\n          \"kind\": \"text\",\n          \"required\": false,\n          \"help\": \"A new immutable result will be created.\"\n        }\n      ],\n      \"claimBoundary\": \"Arithmetic fidelity, predictive readout and behavioral/causal evidence are different. This operation supplies no behavioral causal test; null draws are comparators, not calibrated p-values. The current batch implementation requires OptVec artifact metadata for layer and dose; other artifact types are not yet accepted.\",\n      \"questions\": [\n        \"Which intervention, lens and probe distribution answer the question?\",\n        \"What observation layers and dose are justified?\",\n        \"What separate controlled behavioral study will test any causal interpretation?\"\n      ]\n    },\n    {\n      \"id\": \"rescore-style\",\n      \"title\": \"Rescore existing generations for style\",\n      \"method\": \"style\",\n      \"purpose\": \"Apply a pinned reasoning-style taxonomy to a completed generation run.\",\n      \"fields\": [\n        {\n          \"id\": \"experiment\",\n          \"label\": \"Study name\",\n          \"kind\": \"text\",\n          \"required\": true,\n          \"help\": \"\"\n        },\n        {\n          \"id\": \"sourceRun\",\n          \"label\": \"Completed generation run\",\n          \"kind\": \"file\",\n          \"required\": true,\n          \"help\": \"\"\n        }\n      ],\n      \"claimBoundary\": \"Rescoring changes measurement, not the original generations. The source epoch gate still applies.\",\n      \"questions\": [\n        \"Which taxonomy is pinned, and why does it measure the intended construct?\",\n        \"Is this a planned measurement or a post-hoc analysis?\"\n      ]\n    },\n    {\n      \"id\": \"sae-family-report\",\n      \"title\": \"Compare intervention families\",\n      \"method\": \"sae\",\n      \"purpose\": \"Produce a descriptive cross-family report from arti